package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.apache.commons.math3.exception.MathException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FDistributionImpl#inverseCumulativeProbability.
 */
public class FDistributionImpl_inverseCumulativeProbability_TriageGen0Test {

    private FDistributionImpl distribution;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        // Standard F-distribution parameters: df1=5, df2=10
        distribution = new FDistributionImpl(5.0, 10.0);
    }

    @Test
    public void testInverseCumulativeProbability_PZero() throws MathException {
        // Tests the first branch: if (p == 0)
        double result = distribution.inverseCumulativeProbability(0.0);
        Assert.assertEquals(0.0, result, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_POne() throws MathException {
        // Tests the second branch: if (p == 1)
        double result = distribution.inverseCumulativeProbability(1.0);
        Assert.assertTrue(Double.isInfinite(result));
        Assert.assertEquals(Double.POSITIVE_INFINITY, result, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_NormalRange() throws MathException {
        // Tests the final return: super.inverseCumulativeProbability(p)
        // For F(5, 10), p=0.5 is the median.
        double p = 0.5;
        double result = distribution.inverseCumulativeProbability(p);

        // Verify that the result is a valid positive number
        Assert.assertTrue("Result should be positive", result > 0);

        // Verify consistency: cumulativeProbability(inverseCumulativeProbability(p)) should be p
        double checkP = distribution.cumulativeProbability(result);
        Assert.assertEquals(p, checkP, 1e-6);
    }

    @Test(expected = MathException.class)
    public void testInverseCumulativeProbability_InvalidProbabilityLow() throws MathException {
        // Testing behavior for p < 0 (though not explicitly handled by if-branches, 
        // it should trigger MathException in super or validation)
        distribution.inverseCumulativeProbability(-0.1);
    }

    @Test(expected = MathException.class)
    public void testInverseCumulativeProbability_InvalidProbabilityHigh() throws MathException {
        // Testing behavior for p > 1
        distribution.inverseCumulativeProbability(1.1);
    }
}
